<?php
namespace App\Http\Controllers\Sales;use App\Http\Controllers\Controller;use App\Models\{AgentCommission,TravelAgent};use Illuminate\Http\Request;
class TravelAgentController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('sales.agents',['agents'=>TravelAgent::where('property_id',$p)->latest()->paginate(30),'commissions'=>AgentCommission::where('property_id',$p)->with('agent')->latest()->limit(50)->get()]);}public function store(Request $r){$d=$r->validate(['name'=>'required|max:180','code'=>'required|max:30','email'=>'nullable|email','phone'=>'nullable|max:50','contact_person'=>'nullable|max:120','commission_percent'=>'nullable|numeric|min:0|max:100','credit_limit'=>'nullable|numeric|min:0','credit_days'=>'nullable|integer|min:0']);TravelAgent::create([...$d,'property_id'=>auth()->user()->property_id]);return back()->with('success','Travel agent created.');}}
